func TestRunResultsetOrderbyMultiDeliveryDiffRejectsTraceMutations(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	tests := []struct {
		name   string
		mutate func(*compat.Trace)
	}{
		{
			name: "pattern-value",
			mutate: func(trace *compat.Trace) {
				trace.Records[0].New[0].Fields["a.theString"] = "Z"
			},
		},
		{
			name: "pattern-row-order",
			mutate: func(trace *compat.Trace) {
				trace.Records[0].New[0], trace.Records[0].New[1] = trace.Records[0].New[1], trace.Records[0].New[0]
			},
		},
		{
			name: "pattern-limit-count",
			mutate: func(trace *compat.Trace) {
				trace.Records[1].New = trace.Records[1].New[:2]
			},
		},
		{
			name: "pattern-limit-value",
			mutate: func(trace *compat.Trace) {
				trace.Records[1].New[2].Fields["a.theString"] = "Z"
			},
		},
		{
			name: "groupwin-time-value",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].New[0].Fields["theString"] = "Z"
			},
		},
		{
			name: "groupwin-time-row-order",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].New[0], trace.Records[2].New[1] = trace.Records[2].New[1], trace.Records[2].New[0]
			},
		},
		{
			name: "record-order",
			mutate: func(trace *compat.Trace) {
				trace.Records[1], trace.Records[2] = trace.Records[2], trace.Records[1]
			},
		},
		{
			name: "record-count",
			mutate: func(trace *compat.Trace) {
				trace.Records = trace.Records[:len(trace.Records)-1]
			},
		},
		{
			name: "time-boundary",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].Time = "1970-01-01T00:00:12Z"
			},
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			javaTracePath := writeJavaTraceFixtureFromEvidence(t,
				filepath.Join(root, resultsetOrderbyMultiDeliveryID+".evidence.json"), test.mutate)
			evidencePath := filepath.Join(t.TempDir(), resultsetOrderbyMultiDeliveryID+".evidence.json")
			var stdout, stderr bytes.Buffer
			code := Run([]string{
				"-mode", resultsetOrderbyMultiDeliveryID + "-diff",
				"-scenario", filepath.Join(root, resultsetOrderbyMultiDeliveryID+".json"),
				"-java-trace", javaTracePath,
				"-evidence", evidencePath,
			}, &stdout, &stderr)
			if code == 0 {
				t.Fatalf("mutation %q unexpectedly passed; stdout=%q stderr=%q", test.name, stdout.String(), stderr.String())
			}
			evidence, err := loadDifferentialEvidenceFile(evidencePath)
			if err != nil {
				t.Fatal(err)
			}
			if evidence.Status != "different" || len(evidence.Differences) == 0 {
				t.Fatalf("mutation %q evidence = %#v", test.name, evidence)
			}
		})
	}
}

func TestRunResultsetOrderbyMultiDeliveryCheckedInEvidenceMatchesTraceAndReplay(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	javaTrace, err := loadTraceFile(filepath.Join(root, resultsetOrderbyMultiDeliveryID+".trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	goTrace, err := loadTraceFile(filepath.Join(root, resultsetOrderbyMultiDeliveryID+".go.trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	evidence, err := loadDifferentialEvidenceFile(filepath.Join(root, resultsetOrderbyMultiDeliveryID+".evidence.json"))
	if err != nil {
		t.Fatal(err)
	}
	if evidence.Status != "passing" || len(evidence.Differences) != 0 {
		t.Fatalf("checked-in evidence = %#v", evidence)
	}
	if differences := compat.DiffTraces(javaTrace, evidence.JavaTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Java trace differs from checked-in trace: %#v", differences)
	}
	if differences := compat.DiffTraces(goTrace, evidence.GoTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from evidence Go trace: %#v", differences)
	}
	if evidence.JavaCommit != resultsetOrderbyMultiDeliveryJavaCommit ||
		!reflect.DeepEqual(evidence.JavaRuntimeIDs, resultsetOrderbyMultiDeliveryJavaRuntimeIDs) ||
		!reflect.DeepEqual(evidence.JavaSourceFiles, []string{resultsetOrderbyMultiDeliverySource}) ||
		!reflect.DeepEqual(evidence.JavaExecutions, resultsetOrderbyMultiDeliveryJavaExecutions) {
		t.Fatalf("checked-in Java metadata = %#v", evidence)
	}
	assertResultsetOrderbyMultiDeliveryTrace(t, javaTrace)
	assertResultsetOrderbyMultiDeliveryTrace(t, goTrace)

	scenarioPath := filepath.Join(root, resultsetOrderbyMultiDeliveryID+".json")
	scenarioData, err := os.ReadFile(scenarioPath)
	if err != nil {
		t.Fatal(err)
	}
	var rawScenario struct {
		Version string        `json:"version"`
		ID      string        `json:"id"`
		Steps   []compat.Step `json:"steps"`
	}
	if err := json.Unmarshal(scenarioData, &rawScenario); err != nil {
		t.Fatal(err)
	}
	scenario := compat.Scenario{Version: rawScenario.Version, ID: rawScenario.ID, Steps: rawScenario.Steps}
	scenarioJSON, err := json.Marshal(scenario)
	if err != nil {
		t.Fatal(err)
	}
	evidenceScenarioJSON, err := json.Marshal(evidence.Scenario)
	if err != nil {
		t.Fatal(err)
	}
	var scenarioValue, evidenceScenarioValue any
	if err := json.Unmarshal(scenarioJSON, &scenarioValue); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(evidenceScenarioJSON, &evidenceScenarioValue); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(scenarioValue, evidenceScenarioValue) {
		t.Fatal("checked-in evidence scenario differs from checked-in scenario")
	}

	canonicalEvidence, err := compat.NewDifferentialEvidence(
		resultsetOrderbyMultiDeliveryJavaCommit,
		resultsetOrderbyMultiDeliveryJavaRuntimeIDs,
		[]string{resultsetOrderbyMultiDeliverySource},
		resultsetOrderbyMultiDeliveryJavaExecutions,
		scenario, javaTrace, evidence.GoTrace)
	if err != nil {
		t.Fatal(err)
	}
	if canonicalEvidence.Status != "passing" || len(canonicalEvidence.Differences) != 0 {
		t.Fatalf("checked-in Java trace is not a passing comparison: %#v", canonicalEvidence.Differences)
	}

	var stdout, stderr bytes.Buffer
	if code := Run([]string{
		"-mode", resultsetOrderbyMultiDeliveryID,
		"-scenario", scenarioPath,
	}, &stdout, &stderr); code != 0 {
		t.Fatalf("replay exit code = %d, stderr = %q", code, stderr.String())
	}
	replayed, err := compat.LoadTrace(strings.NewReader(stdout.String()))
	if err != nil {
		t.Fatal(err)
	}
	if differences := compat.DiffTraces(evidence.GoTrace, replayed); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from current replay: %#v", differences)
	}
	assertResultsetOrderbyMultiDeliveryTrace(t, replayed)
}

