func assertResultsetOrderbyMultiDeliveryTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != resultsetOrderbyMultiDeliveryID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 3 {
		t.Fatalf("trace records = %d, want 3", len(trace.Records))
	}
	batches := []struct {
		caseName string
		field    string
		time     string
		values   []string
	}{
		{caseName: "multi-delivery-pattern", field: "a.theString", time: "1970-01-01T00:00:00Z", values: []string{"A2", "A1"}},
		{caseName: "multi-delivery-pattern-output-limit", field: "a.theString", time: "1970-01-01T00:00:00Z", values: []string{"A3", "A2", "A1"}},
		{caseName: "multi-delivery-groupwin-time", field: "theString", time: "1970-01-01T00:00:11Z", values: []string{"A2", "A1"}},
	}
	for recordIndex, batch := range batches {
		record := trace.Records[recordIndex]
		if record.Case != batch.caseName ||
			record.Operation != "listener" || record.Statement != "s0" ||
			record.Sequence != 1 || record.Time != batch.time ||
			len(record.New) != len(batch.values) || len(record.Old) != 0 {
			t.Fatalf("record %d metadata/shape = %#v", recordIndex, record)
		}
		for rowIndex, row := range record.New {
			if row.Kind != "row" || len(row.Fields) != 1 ||
				row.Fields[batch.field] != batch.values[rowIndex] {
				t.Fatalf("record %d row %d shape/identity = %#v", recordIndex, rowIndex, row)
			}
		}
	}
}

