func valueMatches(value any, want int64) bool {
	number, ok := numberValueOf(value)
	return ok && number == want
}

func numberValueOf(value any) (int64, bool) {
	switch current := value.(type) {
	case int:
		return int64(current), true
	case int64:
		return current, true
	case json.Number:
		parsed, err := current.Int64()
		return parsed, err == nil
	}
	return 0, false
}

func assertResultsetOutputLimitChangesetTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != resultsetOutputLimitChangesetID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	const recordsPerRound = 2
	if len(trace.Records) != resultsetOutputLimitChangesetRounds*recordsPerRound {
		t.Fatalf("trace records = %d, want %d", len(trace.Records), resultsetOutputLimitChangesetRounds*recordsPerRound)
	}
	// The buffering delta-set view reports five buffered interim pairs exactly
	// on the DISABLE_OUTPUTLIMIT_OPT rounds of the pinned matrix; every other
	// hint and output kind keeps the counter at zero between sends.
	countingRounds := map[int]bool{4: true, 8: true, 11: true, 16: true, 19: true, 24: true, 27: true, 31: true, 34: true}
	for round := 0; round < resultsetOutputLimitChangesetRounds; round++ {
		before := trace.Records[round*recordsPerRound]
		after := trace.Records[round*recordsPerRound+1]
		wantBefore := int64(0)
		if countingRounds[round] {
			wantBefore = resultsetOutputLimitChangesetSends
		}
		wantBeforeTime := time.Unix(int64(round), 0).UTC().Format(time.RFC3339)
		wantAfterTime := time.Unix(int64(round+1), 0).UTC().Format(time.RFC3339)
		if before.Case != resultsetOutputLimitChangesetCaseName ||
			before.Operation != "changeset" || before.Statement != "s0" ||
			before.Sequence != uint64(round*recordsPerRound+1) || before.Time != wantBeforeTime ||
			!valueMatches(before.Value, wantBefore) {
			t.Fatalf("round %d before record = %#v", round, before)
		}
		if after.Case != resultsetOutputLimitChangesetCaseName ||
			after.Operation != "changeset" || after.Statement != "s0" ||
			after.Sequence != uint64(round*recordsPerRound+2) || after.Time != wantAfterTime ||
			!valueMatches(after.Value, 0) {
			t.Fatalf("round %d after record = %#v", round, after)
		}
	}
}
