func assertEplSubselectOrderOfEvalIndexTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != eplSubselectOrderOfEvalIndexID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 45 {
		t.Fatalf("trace records = %d, want 45", len(trace.Records))
	}
	rowFields := func(record compat.TraceRecord) map[string]any {
		if record.Operation != "listener" || record.Statement != "s0" ||
			record.Time != "1970-01-01T00:00:00Z" || len(record.New) != 1 || len(record.Old) != 0 {
			t.Fatalf("record shape = %#v", record)
		}
		return record.New[0].Fields
	}
	// Case correlated-subquery-order: window columns render as row arrays.
	for index, record := range trace.Records[0:2] {
		fields := rowFields(record)
		if record.Case != "correlated-subquery-order" || record.Sequence != uint64(index+1) {
			t.Fatalf("order record %d metadata = %#v", index, record)
		}
		wantTimes := []int{1000, 1010}
		for _, column := range []string{"longItems", "shortItems"} {
			rows, ok := fields[column].([]any)
			if !ok || len(rows) != index+1 {
				t.Fatalf("order record %d column %q = %#v", index, column, fields[column])
			}
			for position, element := range rows {
				fields := element.(map[string]any)["fields"].(map[string]any)
				if !valueMatches(fields["price"], 50) || !valueMatches(fields["securityID"], 1000) ||
					!valueMatches(fields["time"], int64(wantTimes[position])) || !valueMatches(fields["volume"], 1) {
					t.Fatalf("order record %d column %q row %d = %#v", index, column, position, fields)
				}
			}
		}
	}
	// Case order-of-eval-subselect-first: zero records by design.
	// Case index-choices-overdefined-where: 36 records, sequences 1..36.
	nullState := map[string]any{"state": "null"}
	for index, record := range trace.Records[2:38] {
		fields := rowFields(record)
		if record.Case != "index-choices-overdefined-where" || record.Sequence != uint64(index+1) {
			t.Fatalf("index record %d metadata = %#v", index, record)
		}
		if fields["c0"] != "EX" && fields["c0"] != "EY" && fields["c0"] != "A" && fields["c0"] != "B" &&
			fields["c0"] != "C" && fields["c0"] != "D" && fields["c0"] != "E" {
			t.Fatalf("index record %d c0 = %#v", index, fields["c0"])
		}
		if c1, ok := fields["c1"].(string); ok && c1 != "E1" && c1 != "E2" && c1 != "E3" {
			t.Fatalf("index record %d c1 = %#v", index, fields["c1"])
		}
	}
	// Spot-pin the null rows of the index matrix.
	for _, index := range []int{1, 16, 18, 19, 20, 21, 24, 25, 26, 28, 29, 30, 31, 34, 35} {
		fields := trace.Records[2+index].New[0].Fields
		if !reflect.DeepEqual(fields["c1"], nullState) {
			t.Fatalf("index record %d c1 = %#v, want null state", index, fields["c1"])
		}
	}
	// Case unique-index-correlated: 7 records.
	wantCorrelated := []struct {
		c0 int64
		c1 int64
	}{{10, 4}, {11, 3}, {10, 2}, {11, 1}, {10, 4}, {11, 3}, {1, 102}}
	for index, record := range trace.Records[38:45] {
		fields := rowFields(record)
		if record.Case != "unique-index-correlated" || record.Sequence != uint64(index+1) {
			t.Fatalf("correlated record %d metadata = %#v", index, record)
		}
		if !valueMatches(fields["c0"], wantCorrelated[index].c0) || !valueMatches(fields["c1"], wantCorrelated[index].c1) {
			t.Fatalf("correlated record %d fields = %#v", index, fields)
		}
	}
}
