func assertInfraNWTableSubqUncorrelTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != infraNWTableSubqUncorrelID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 67 {
		t.Fatalf("trace records = %d, want 67", len(trace.Records))
	}
	nullState := map[string]any{"state": "null"}
	// Per-case explicit record table (statement, sequence, new/old fields).
	type step struct {
		statement string
		sequence  uint64
		newFields map[string]any
		oldFields map[string]any
	}
	nw := []step{
		{"select", 1, map[string]any{"symbol": "M1", "value": nullState}, nil},
		{"create", 1, map[string]any{"a": "S1", "b": json.Number("1"), "c": json.Number("2")}, nil},
		{"select", 2, map[string]any{"symbol": "M1", "value": "S1"}, nil},
		{"selectTwo", 1, map[string]any{"symbol": "M1", "value": "S1"}, nil},
		{"create", 2, map[string]any{"a": "S2", "b": json.Number("10"), "c": json.Number("20")}, nil},
		{"select", 3, map[string]any{"symbol": "M2", "value": nullState}, nil},
		{"selectTwo", 2, map[string]any{"symbol": "M2", "value": nullState}, nil},
		{"create", 3, nil, map[string]any{"a": "S1", "b": json.Number("1"), "c": json.Number("2")}},
		{"delete", 1, map[string]any{"a": "S1", "b": json.Number("1"), "c": json.Number("2")}, nil},
		{"select", 4, map[string]any{"symbol": "M3", "value": "S2"}, nil},
		{"selectTwo", 3, map[string]any{"symbol": "M3", "value": "S2"}, nil},
		{"create", 4, nil, map[string]any{"a": "S2", "b": json.Number("10"), "c": json.Number("20")}},
		{"delete", 2, map[string]any{"a": "S2", "b": json.Number("10"), "c": json.Number("20")}, nil},
		{"select", 5, map[string]any{"symbol": "M4", "value": nullState}, nil},
		{"selectTwo", 4, map[string]any{"symbol": "M4", "value": nullState}, nil},
		{"create", 5, map[string]any{"a": "S3", "b": json.Number("100"), "c": json.Number("200")}, nil},
		{"select", 6, map[string]any{"symbol": "M5", "value": "S3"}, nil},
		{"selectTwo", 5, map[string]any{"symbol": "M5", "value": "S3"}, nil},
	}
	tbl := []step{
		{"select", 1, map[string]any{"symbol": "M1", "value": nullState}, nil},
		{"select", 2, map[string]any{"symbol": "M1", "value": "S1"}, nil},
		{"selectTwo", 1, map[string]any{"symbol": "M1", "value": "S1"}, nil},
		{"select", 3, map[string]any{"symbol": "M2", "value": nullState}, nil},
		{"selectTwo", 2, map[string]any{"symbol": "M2", "value": nullState}, nil},
		{"delete", 1, map[string]any{"a": "S1", "b": json.Number("1"), "c": json.Number("2")}, nil},
		{"select", 4, map[string]any{"symbol": "M3", "value": "S2"}, nil},
		{"selectTwo", 3, map[string]any{"symbol": "M3", "value": "S2"}, nil},
		{"delete", 2, map[string]any{"a": "S2", "b": json.Number("10"), "c": json.Number("20")}, nil},
		{"select", 5, map[string]any{"symbol": "M4", "value": nullState}, nil},
		{"selectTwo", 4, map[string]any{"symbol": "M4", "value": nullState}, nil},
		{"select", 6, map[string]any{"symbol": "M5", "value": "S3"}, nil},
		{"selectTwo", 5, map[string]any{"symbol": "M5", "value": "S3"}, nil},
	}
	offset := 0
	for _, caseName := range infraNWTableSubqUncorrelCases {
		steps := nw
		if caseName == "table" {
			steps = tbl
		}
		for index, want := range steps {
			record := trace.Records[offset]
			offset++
			if record.Case != caseName || record.Statement != want.statement ||
				record.Sequence != want.sequence || record.Time != "1970-01-01T00:00:00Z" {
				t.Fatalf("%s record %d metadata = %#v", caseName, index, record)
			}
			wantNew, wantOld := want.newFields, want.oldFields
			if wantNew == nil {
				if len(record.New) != 0 {
					t.Fatalf("%s %s seq %d unexpected new = %#v", caseName, record.Statement, record.Sequence, record.New)
				}
			} else if len(record.New) != 1 || !reflect.DeepEqual(record.New[0].Fields, wantNew) {
				t.Fatalf("%s %s seq %d new = %#v, want %#v", caseName, record.Statement, record.Sequence, record.New[0].Fields, wantNew)
			}
			if wantOld == nil {
				if len(record.Old) != 0 {
					t.Fatalf("%s %s seq %d unexpected old = %#v", caseName, record.Statement, record.Sequence, record.Old)
				}
			} else if len(record.Old) != 1 || !reflect.DeepEqual(record.Old[0].Fields, wantOld) {
				t.Fatalf("%s %s seq %d old = %#v, want %#v", caseName, record.Statement, record.Sequence, record.Old[0].Fields, wantOld)
			}
		}
	}
	if offset != len(trace.Records) {
		t.Fatalf("trace has %d trailing records", len(trace.Records)-offset)
	}
}

