func TestRunInfraNamedWindowOnUpdateDiffRejectsTraceMutations(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	tests := []struct {
		name   string
		mutate func(*compat.Trace)
	}{
		{
			name: "update-new-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].New[0].Fields["intPrimitive"] = json.Number("301")
			},
		},
		{
			name: "update-old-missing",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].Old = nil
			},
		},
		{
			name: "insert-new-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[4].New[0].Fields["theString"] = "EX"
			},
		},
		{
			name: "statement-swap",
			mutate: func(trace *compat.Trace) {
				trace.Records[1].Statement = "update"
			},
		},
		{
			name: "sequence-drift",
			mutate: func(trace *compat.Trace) {
				trace.Records[2].Sequence = 4
			},
		},
		{
			name: "union-snapshot-order",
			mutate: func(trace *compat.Trace) {
				trace.Records[7].New[0], trace.Records[7].New[1] = trace.Records[7].New[1], trace.Records[7].New[0]
			},
		},
		{
			name: "multikey-snapshot-leak",
			mutate: func(trace *compat.Trace) {
				trace.Records[9].New = append(trace.Records[9].New, compat.ResultRecord{
					Kind:   "row",
					Fields: map[string]any{"id": "IDX", "value": json.Number("14")},
				})
			},
		},
		{
			name: "record-count-short",
			mutate: func(trace *compat.Trace) {
				trace.Records = trace.Records[:9]
			},
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			javaTracePath := writeJavaTraceFixtureFromEvidence(t,
				filepath.Join(root, infraNamedWindowOnUpdateID+".evidence.json"), test.mutate)
			evidencePath := filepath.Join(t.TempDir(), infraNamedWindowOnUpdateID+".evidence.json")
			var stdout, stderr bytes.Buffer
			code := Run([]string{
				"-mode", infraNamedWindowOnUpdateID + "-diff",
				"-scenario", filepath.Join(root, infraNamedWindowOnUpdateID+".json"),
				"-java-trace", javaTracePath,
				"-evidence", evidencePath,
			}, &stdout, &stderr)
			if code == 0 {
				t.Fatalf("mutation %q unexpectedly passed; stdout=%q stderr=%q", test.name, stdout.String(), stderr.String())
			}
			evidence, err := loadDifferentialEvidenceFile(evidencePath)
			if err != nil {
				t.Fatal(err)
			}
			if evidence.Status != "different" || len(evidence.Differences) == 0 {
				t.Fatalf("mutation %q evidence = %#v", test.name, evidence)
			}
		})
	}
}

func TestRunInfraNamedWindowOnUpdateCheckedInEvidenceMatchesTraceAndReplay(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	javaTrace, err := loadTraceFile(filepath.Join(root, infraNamedWindowOnUpdateID+".trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	goTrace, err := loadTraceFile(filepath.Join(root, infraNamedWindowOnUpdateID+".go.trace.json"))
	if err != nil {
		t.Fatal(err)
	}
	evidence, err := loadDifferentialEvidenceFile(filepath.Join(root, infraNamedWindowOnUpdateID+".evidence.json"))
	if err != nil {
		t.Fatal(err)
	}
	if evidence.Status != "passing" || len(evidence.Differences) != 0 {
		t.Fatalf("checked-in evidence = %#v", evidence)
	}
	if differences := compat.DiffTraces(javaTrace, evidence.JavaTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Java trace differs from checked-in trace: %#v", differences)
	}
	if differences := compat.DiffTraces(goTrace, evidence.GoTrace); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from evidence Go trace: %#v", differences)
	}
	if evidence.JavaCommit != infraNamedWindowOnUpdateJavaCommit ||
		!reflect.DeepEqual(evidence.JavaRuntimeIDs, infraNamedWindowOnUpdateJavaRuntimeIDs) ||
		!reflect.DeepEqual(evidence.JavaSourceFiles, []string{infraNamedWindowOnUpdateSource}) ||
		!reflect.DeepEqual(evidence.JavaExecutions, infraNamedWindowOnUpdateJavaExecutions) {
		t.Fatalf("checked-in Java metadata = %#v", evidence)
	}
	assertInfraNamedWindowOnUpdateTrace(t, javaTrace)
	assertInfraNamedWindowOnUpdateTrace(t, goTrace)

	scenarioPath := filepath.Join(root, infraNamedWindowOnUpdateID+".json")
	scenarioData, err := os.ReadFile(scenarioPath)
	if err != nil {
		t.Fatal(err)
	}
	var rawScenario struct {
		Version string        `json:"version"`
		ID      string        `json:"id"`
		Steps   []compat.Step `json:"steps"`
	}
	if err := json.Unmarshal(scenarioData, &rawScenario); err != nil {
		t.Fatal(err)
	}
	scenario := compat.Scenario{Version: rawScenario.Version, ID: rawScenario.ID, Steps: rawScenario.Steps}
	scenarioJSON, err := json.Marshal(scenario)
	if err != nil {
		t.Fatal(err)
	}
	evidenceScenarioJSON, err := json.Marshal(evidence.Scenario)
	if err != nil {
		t.Fatal(err)
	}
	var scenarioValue, evidenceScenarioValue any
	if err := json.Unmarshal(scenarioJSON, &scenarioValue); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(evidenceScenarioJSON, &evidenceScenarioValue); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(scenarioValue, evidenceScenarioValue) {
		t.Fatal("checked-in evidence scenario differs from checked-in scenario")
	}

	canonicalEvidence, err := compat.NewDifferentialEvidence(
		infraNamedWindowOnUpdateJavaCommit,
		infraNamedWindowOnUpdateJavaRuntimeIDs,
		[]string{infraNamedWindowOnUpdateSource},
		infraNamedWindowOnUpdateJavaExecutions,
		scenario, javaTrace, evidence.GoTrace)
	if err != nil {
		t.Fatal(err)
	}
	if canonicalEvidence.Status != "passing" || len(canonicalEvidence.Differences) != 0 {
		t.Fatalf("checked-in Java trace is not a passing comparison: %#v", canonicalEvidence.Differences)
	}

	var stdout, stderr bytes.Buffer
	if code := Run([]string{
		"-mode", infraNamedWindowOnUpdateID,
		"-scenario", scenarioPath,
	}, &stdout, &stderr); code != 0 {
		t.Fatalf("replay exit code = %d, stderr = %q", code, stderr.String())
	}
	replayed, err := compat.LoadTrace(strings.NewReader(stdout.String()))
	if err != nil {
		t.Fatal(err)
	}
	if differences := compat.DiffTraces(evidence.GoTrace, replayed); len(differences) != 0 {
		t.Fatalf("checked-in evidence Go trace differs from current replay: %#v", differences)
	}
	assertInfraNamedWindowOnUpdateTrace(t, replayed)
}

func TestRunInfraNamedWindowOnUpdateRejectsMalformedRawScenario(t *testing.T) {
	root := filepath.Join("..", "..", "..", "testdata", "parity")
	data, err := os.ReadFile(filepath.Join(root, infraNamedWindowOnUpdateID+".json"))
	if err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name   string
		mutate func([]byte) []byte
	}{
		{name: "top-level-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"steps": [`), []byte(`"extra": 0, "steps": [`), 1)
		}},
		{name: "case-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"case": "intersect"`), []byte(`"case": "intersect", "extra": 0`), 1)
		}},
		{name: "case-runtime-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"runtimeId": "java-runtime-f921cf2543cbb10b4150"`), []byte(`"runtimeId": "java-runtime-wrong"`), 1)
		}},
		{name: "case-ordinal-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"ordinal": 1`), []byte(`"ordinal": 0`), 1)
		}},
		{name: "create-epl-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`@public create window MyWindowMDW#unique(theString)#length(2)`), []byte(`@public create window MyWindowMDW#unique(theString)`), 1)
		}},
		{name: "update-epl-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`set intPrimitive=intPrimitive*100`), []byte(`set intPrimitive=intPrimitive*101`), 1)
		}},
		{name: "public-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`@name('create') @public create window MyWindow#keepall`), []byte(`@name('create') create window MyWindow#keepall`), 1)
		}},
		{name: "snapshot-mode-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`{"op": "snapshot", "case": "union", "statement": "create"}`), []byte(`{"op": "snapshot", "case": "union", "statement": "create", "mode": "any"}`), 1)
		}},
		{name: "payload-extra", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`"id": "E2"`), []byte(`"id": "E2", "extra": 0`), 1)
		}},
		{name: "payload-value-drift", mutate: func(data []byte) []byte {
			return bytes.Replace(data, []byte(`{"theString": "E1", "intPrimitive": 2}`), []byte(`{"theString": "E1", "intPrimitive": 9}`), 1)
		}},
		{name: "trailing-json", mutate: func(data []byte) []byte {
			return append(append([]byte(nil), data...), []byte("\n{}\n")...)
		}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			mutated := test.mutate(data)
			if bytes.Equal(mutated, data) {
				t.Fatalf("raw mutation %q did not change scenario", test.name)
			}
			scenarioPath := filepath.Join(t.TempDir(), "scenario.json")
			if err := os.WriteFile(scenarioPath, mutated, 0o644); err != nil {
				t.Fatal(err)
			}
			var stdout, stderr bytes.Buffer
			if code := Run([]string{
				"-mode", infraNamedWindowOnUpdateID,
				"-scenario", scenarioPath,
			}, &stdout, &stderr); code == 0 {
				t.Fatalf("malformed scenario %q unexpectedly replayed: stdout=%q stderr=%q", test.name, stdout.String(), stderr.String())
			}
		})
	}
}

