func assertInfraNamedWindowOnUpdateTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != infraNamedWindowOnUpdateID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 10 {
		t.Fatalf("trace records = %d, want 10", len(trace.Records))
	}
	row := func(fields map[string]any) compat.ResultRecord {
		return compat.ResultRecord{Kind: "row", Fields: fields}
	}
	type step struct {
		operation string
		statement string
		sequence  uint64
		newRows   []compat.ResultRecord
		oldRows   []compat.ResultRecord
		anyOrder  bool
		byID      bool
	}
	intersect := []step{
		{"listener", "create", 1, []compat.ResultRecord{row(map[string]any{"theString": "E1", "intPrimitive": json.Number("2")})}, nil, false, false},
		{"listener", "create", 2, []compat.ResultRecord{row(map[string]any{"theString": "E2", "intPrimitive": json.Number("3")})}, nil, false, false},
		{"listener", "create", 3, []compat.ResultRecord{row(map[string]any{"theString": "E2", "intPrimitive": json.Number("300")})}, []compat.ResultRecord{row(map[string]any{"theString": "E2", "intPrimitive": json.Number("3")})}, false, false},
		{"snapshot", "create", 0, []compat.ResultRecord{
			row(map[string]any{"theString": "E1", "intPrimitive": json.Number("2")}),
			row(map[string]any{"theString": "E2", "intPrimitive": json.Number("300")}),
		}, nil, true, false},
	}
	union := append([]step{}, intersect[:3]...)
	union = append(union, step{"snapshot", "create", 0, []compat.ResultRecord{
		row(map[string]any{"theString": "E1", "intPrimitive": json.Number("2")}),
		row(map[string]any{"theString": "E2", "intPrimitive": json.Number("300")}),
	}, nil, false, false})
	offset := 0
	for _, caseName := range infraNamedWindowOnUpdateCases {
		var steps []step
		switch caseName {
		case "intersect":
			steps = intersect
		case "union":
			steps = union
		case "multikey-array":
			steps = []step{{"snapshot", "create", 0, []compat.ResultRecord{
				row(map[string]any{"id": "E1", "value": json.Number("13")}),
				row(map[string]any{"id": "E2", "value": json.Number("10")}),
				row(map[string]any{"id": "E3", "value": json.Number("11")}),
				row(map[string]any{"id": "E4", "value": json.Number("12")}),
			}, nil, true, true}}
		default:
			steps = []step{{"snapshot", "create", 0, []compat.ResultRecord{
				row(map[string]any{"id": "ID1", "value": json.Number("12")}),
				row(map[string]any{"id": "ID2", "value": json.Number("10")}),
				row(map[string]any{"id": "ID3", "value": json.Number("11")}),
			}, nil, true, true}}
		}
		for index, want := range steps {
			record := trace.Records[offset]
			offset++
			if record.Case != caseName || record.Operation != want.operation || record.Statement != want.statement ||
				record.Sequence != want.sequence || record.Time != "1970-01-01T00:00:00Z" {
				t.Fatalf("%s record %d metadata = %#v", caseName, index, record)
			}
			assertOnUpdateRows(t, caseName, index, "new", record.New, want.newRows, want.anyOrder, want.byID)
			assertOnUpdateRows(t, caseName, index, "old", record.Old, want.oldRows, want.anyOrder, want.byID)
		}
	}
	if offset != len(trace.Records) {
		t.Fatalf("trace has %d trailing records", len(trace.Records)-offset)
	}
}

func assertOnUpdateRows(t *testing.T, caseName string, index int, stream string, got, want []compat.ResultRecord, anyOrder, byID bool) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s record %d %s rows = %d, want %d (%#v)", caseName, index, stream, len(got), len(want), got)
	}
	if anyOrder {
		key := func(record compat.ResultRecord) string {
			if byID {
				return fmt.Sprint(record.Fields["id"])
			}
			return fmt.Sprint(record.Fields["theString"])
		}
		gotKeys := map[string]compat.ResultRecord{}
		for _, record := range got {
			gotKeys[key(record)] = record
		}
		for _, record := range want {
			matched, ok := gotKeys[key(record)]
			if !ok || !reflect.DeepEqual(matched.Fields, record.Fields) {
				t.Fatalf("%s record %d %s rows mismatch: got %#v want %#v", caseName, index, stream, got, want)
			}
		}
		return
	}
	for i := range want {
		if !reflect.DeepEqual(got[i].Fields, want[i].Fields) {
			t.Fatalf("%s record %d %s row %d = %#v, want %#v", caseName, index, stream, i, got[i].Fields, want[i].Fields)
		}
	}
}

