func assertInfraNamedWindowInsertFromTrace(t *testing.T, trace compat.Trace) {
	t.Helper()
	if trace.Version != compat.ScenarioVersion || trace.ID != infraNamedWindowInsertFromID {
		t.Fatalf("trace identity = %q/%q", trace.Version, trace.ID)
	}
	if len(trace.Records) != 18 {
		t.Fatalf("trace records = %d, want 18", len(trace.Records))
	}
	row := func(fields map[string]any) compat.ResultRecord {
		return compat.ResultRecord{Kind: "row", Fields: fields}
	}
	nullState := map[string]any{"state": "null"}
	type step struct {
		caseName  string
		operation string
		statement string
		sequence  uint64
		newRows   []compat.ResultRecord
		anyOrder  bool
	}
	steps := []step{
		{"create-after-named", "listener", "windowOne", 1,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("1"), "theString": "E1"})}, false},
		{"create-after-named", "listener", "selectOne", 1,
			[]compat.ResultRecord{row(map[string]any{"theString": "E1"})}, false},
		{"insert-where-type-filter", "listener", "window", 1,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("1"), "theString": "A1"})}, false},
		{"insert-where-type-filter", "listener", "window", 2,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("1"), "theString": "B2"})}, false},
		{"insert-where-type-filter", "listener", "window", 3,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("1"), "theString": "C3"})}, false},
		{"insert-where-type-filter", "listener", "window", 4,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("4"), "theString": "A4"})}, false},
		{"insert-where-type-filter", "listener", "window", 5,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("4"), "theString": "C5"})}, false},
		{"insert-where-type-filter", "snapshot", "windowTwo", 0,
			[]compat.ResultRecord{
				row(map[string]any{"theString": "A1"}),
				row(map[string]any{"theString": "B2"}),
				row(map[string]any{"theString": "C3"}),
				row(map[string]any{"theString": "A4"}),
				row(map[string]any{"theString": "C5"}),
			}, false},
		{"insert-where-type-filter", "snapshot", "windowThree", 0,
			[]compat.ResultRecord{
				row(map[string]any{"theString": "A1"}),
				row(map[string]any{"theString": "A4"}),
			}, false},
		{"insert-where-type-filter", "snapshot", "windowFour", 0,
			[]compat.ResultRecord{
				row(map[string]any{"theString": "C3"}),
				row(map[string]any{"theString": "C5"}),
			}, true},
		{"insert-where-type-filter", "listener", "windowTwo", 1,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("-9"), "theString": "B9"})}, false},
		{"insert-where-type-filter", "listener", "window", 6,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("-8"), "theString": "A8"})}, false},
		{"insert-where-type-filter", "listener", "windowThree", 1,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("-7"), "theString": "C7"})}, false},
		{"insert-where-type-filter", "listener", "windowFour", 1,
			[]compat.ResultRecord{row(map[string]any{"intPrimitive": json.Number("-6"), "theString": "D6"})}, false},
		{"lenient-map", "snapshot", "window", 0,
			[]compat.ResultRecord{row(map[string]any{"c0": "E1", "c1": nullState})}, false},
		{"lenient-map", "snapshot", "window", 0,
			[]compat.ResultRecord{
				row(map[string]any{"c0": "E1", "c1": nullState}),
				row(map[string]any{"c0": nullState, "c1": json.Number("10")}),
			}, false},
		{"lenient-objectarray", "snapshot", "window", 0,
			[]compat.ResultRecord{row(map[string]any{"c0": "E1", "c1": nullState})}, false},
		{"lenient-objectarray", "snapshot", "window", 0,
			[]compat.ResultRecord{
				row(map[string]any{"c0": "E1", "c1": nullState}),
				row(map[string]any{"c0": nullState, "c1": json.Number("10")}),
			}, false},
	}
	for index, want := range steps {
		record := trace.Records[index]
		if record.Case != want.caseName || record.Operation != want.operation || record.Statement != want.statement ||
			record.Sequence != want.sequence || record.Time != "1970-01-01T00:00:00Z" {
			t.Fatalf("record %d metadata = %#v", index, record)
		}
		if len(record.New) != len(want.newRows) {
			t.Fatalf("%s %s seq %d new rows = %d, want %d", want.caseName, want.statement, want.sequence, len(record.New), len(want.newRows))
		}
		if want.anyOrder {
			for _, wanted := range want.newRows {
				found := false
				for _, got := range record.New {
					if reflect.DeepEqual(got.Fields, wanted.Fields) {
						found = true
						break
					}
				}
				if !found {
					t.Fatalf("%s %s seq %d new rows = %#v, want %#v", want.caseName, want.statement, want.sequence, record.New, want.newRows)
				}
			}
			continue
		}
		for i := range want.newRows {
			if !reflect.DeepEqual(record.New[i].Fields, want.newRows[i].Fields) {
				t.Fatalf("%s %s seq %d new row %d = %#v, want %#v", want.caseName, want.statement, want.sequence, i, record.New[i].Fields, want.newRows[i].Fields)
			}
		}
		if len(record.Old) != 0 {
			t.Fatalf("%s %s seq %d unexpected old = %#v", want.caseName, want.statement, want.sequence, record.Old)
		}
	}
}

func mustInt64(t *testing.T, value any) int64 {
	number, ok := value.(json.Number)
	if !ok {
		t.Fatalf("value %#v is not a JSON number", value)
	}
	parsed, err := number.Int64()
	if err != nil {
		t.Fatalf("value %#v is not an int64", value)
	}
	return parsed
}

